import type { Argv, ArgumentsCamelCase } from 'yargs'
import { Connector } from '@servicenow/sdk-api'
import type { LazyCredential } from '@servicenow/sdk-api/credentials'
import { credentialProvider } from '../../auth'
import { logger } from '../../logger'
import { withTelemetryEvent } from '../../telemetry'
import { printMachineEnvelope } from '../../util/json-select'
import type { CicdArguments, CicdInterpretedResult, CicdOperation, CicdResultBody } from './types'
import { applyParamOptions, extractParamPayload } from './param-spec'
import { extractErrorMessage, pollProgress, type ProgressOutcome } from './poller'

const DEFAULT_POLL_TIMEOUT_MS = 15 * 60 * 1000

interface CommonArguments {
    auth?: string
    output?: 'json' | 'raw'
    select?: string
    wait?: boolean
    pollTimeout?: number
}

type SuccessEnvelope = {
    ok: true
    result: CicdResultBody
    progress?: ProgressOutcome
    interpretedResult?: CicdInterpretedResult // Only if the command has a postProcess
}

type ErrorEnvelope = {
    ok: false
    error: { message: string }
}

export interface CicdCommandModule {
    command: string
    describe: string
    builder: (yargs: Argv) => Argv
    handler: (args: ArgumentsCamelCase<CommonArguments & Record<string, unknown>>) => Promise<void>
}

/** The full command path for display/logging, e.g. 'testsuite run' or 'install'. */
export function fullCommandPath(operation: CicdOperation): string {
    return operation.group ? `${operation.group} ${operation.command}` : operation.command
}

/**
 * Turns a declarative CicdOperation into a full yargs command module. The `command` string here is
 * always the leaf name — grouped operations are registered inside their group's sub-builder, so the
 * group segment is added there, not baked into this module.
 */
export function createOperationCommand(operation: CicdOperation): CicdCommandModule {
    return {
        command: operation.command,
        describe: operation.describe,
        builder(yargs: Argv) {
            let y = applyParamOptions(yargs, operation.params)
            y = y
                .option('auth', {
                    alias: 'a',
                    describe: 'Credential alias to use for authentication with instance',
                    type: 'string',
                })
                .option('output', {
                    alias: 'o',
                    describe: 'Output format: json for a machine-readable envelope, raw to unquote the --select result',
                    type: 'string',
                    choices: ['json', 'raw'] as const,
                })
                .option('select', {
                    alias: 's',
                    describe:
                        'Dot/bracket path to extract from the output (e.g. "result.links.progress.id"). Implies machine-readable output; pair with --output raw for direct use in shell command substitution.',
                    type: 'string',
                })
            if (operation.poll) {
                y = y
                    .option('wait', {
                        describe: 'Wait for the operation to finish by polling its progress',
                        type: 'boolean',
                        default: true,
                    })
                    .option('poll-timeout', {
                        describe: 'Maximum time in milliseconds to wait for the operation to finish',
                        type: 'number',
                        default: DEFAULT_POLL_TIMEOUT_MS,
                    })
            }
            if (operation.check) {
                y = y.check((args) => {
                    const result = operation.check!(args as CicdArguments)
                    if (result !== true) {
                        throw new Error(result)
                    }
                    return true
                })
            }
            return y
        },
        async handler(args) {
            const machineMode = args.output !== undefined || args.select !== undefined
            if (machineMode) {
                logger.setLevel('silent')
            }

            try {
                const errorData = operation.telemetryData?.(args as CicdArguments)
                const credential = await credentialProvider(args.auth)
                await withTelemetryEvent(
                    {
                        event: `cicd.${operation.id}`,
                        sdkDir: __dirname,
                        instanceUrl: credential.getUrl(),
                        ...(errorData ? { errorData } : {}),
                    },
                    async () => {
                        await runOperation(operation, args, machineMode, credential)
                        return operation.telemetryData?.(args as CicdArguments)
                    }
                )
            } catch (error) {
                const message = error instanceof Error ? error.message : String(error)
                if (machineMode) {
                    const envelope: ErrorEnvelope = { ok: false, error: { message } }
                    printMachineEnvelope(envelope, args)
                } else {
                    logger.error(`cicd ${fullCommandPath(operation)} failed:`, error)
                }
                process.exitCode = 1
            }
        },
    }
}

async function runOperation(
    operation: CicdOperation,
    args: ArgumentsCamelCase<CommonArguments & Record<string, unknown>>,
    machineMode: boolean,
    credential: LazyCredential
): Promise<void> {
    const connector = new Connector(credential)

    if (operation.resolve) {
        const resolved = await operation.resolve({ connector, args: args as CicdArguments })
        if (resolved) {
            Object.assign(args, resolved)
        }
    }

    const { body, query } = extractParamPayload(operation.params, args as CicdArguments)
    const path = typeof operation.path === 'function' ? operation.path(args as CicdArguments) : operation.path
    const hasBody = operation.method === 'POST' && Object.keys(body).length > 0

    const response = await connector.fetch(
        path,
        {
            method: operation.method,
            ...(hasBody ? { headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) } : {}),
        },
        query.size > 0 ? query : undefined
    )

    const responseBody = await response.json().catch(() => undefined)
    logger.debug(`Dispatch response from '${path}':`, JSON.stringify(responseBody))
    if (!response.ok) {
        const message = extractErrorMessage(responseBody) ?? response.statusText
        throw new Error(`sn_cicd request to '${path}' failed (${response.status}): ${message}`)
    }

    const result: CicdResultBody = responseBody?.result ?? responseBody ?? {}
    const envelope: SuccessEnvelope = { ok: true, result }

    if (args.wait !== false && operation.poll) {
        const progressId = operation.getProgressId?.(result, args as CicdArguments)
        if (!progressId) {
            throw new Error(`Operation '${operation.id}' expected a progress id in the response but none was found`)
        }

        logger.info(`Waiting for operation to complete (progress id: ${progressId})...`)
        const progress = await pollProgress(connector, progressId, {
            ...(args.pollTimeout !== undefined ? { timeoutMs: args.pollTimeout } : {}),
            onTick: (snapshot) => {
                const version = extractVersionFromStatusDetail(snapshot.statusDetail)
                logger.info(
                    `Still in progress (${snapshot.percentComplete}%${version ? `, version ${version}` : ''})` +
                        (snapshot.statusMessage ? `: ${snapshot.statusMessage}` : '...')
                )
            },
        })
        envelope.progress = progress

        const genericFailureMessage =
            progress.statusMessage || `Operation did not complete successfully (status: ${progress.status})`

        // If the operation has a postProcess, that determines success/failure
        if (operation.postProcess) {
            const interpreted = await operation.postProcess({ connector, progress, progressId })
            envelope.interpretedResult = interpreted

            if (!interpreted.successful) {
                throw new Error(interpreted.displayMessage || genericFailureMessage)
            }
        }

        // Otherwise the progress tracker determines success/failure
        if (!operation.postProcess && !progress.successful) {
            throw new Error(genericFailureMessage)
        }
    }

    printSuccess(operation, envelope, args, machineMode)
}

/**
 * Best-effort extraction of a `version=<x>` token from `ProgressSnapshot.statusDetail`, e.g.
 * `"operation=app_install, app=<sys_id>, version=1.2.3, baseVersion=null, ..."` for app_repo
 * install/publish. `statusDetail`'s format isn't documented/guaranteed for every operation, so this
 * returns `undefined` (rather than throwing) whenever it's missing, empty, or the literal `"null"`.
 */
export function extractVersionFromStatusDetail(statusDetail: string | undefined): string | undefined {
    const match = statusDetail?.match(/(?:^|,)\s*version=([^,]+)/)
    const version = match?.[1]?.trim()
    return version && version !== 'null' ? version : undefined
}

function printSuccess(
    operation: CicdOperation,
    envelope: SuccessEnvelope,
    args: ArgumentsCamelCase<CommonArguments & Record<string, unknown>>,
    machineMode: boolean
): void {
    if (machineMode) {
        printMachineEnvelope(envelope, args)
        return
    }

    // `envelope.result` is the initial dispatch response, captured before polling/waiting even started —
    // it always shows the just-kicked-off state (e.g. status: "0"/Pending), never the outcome. Once
    // polling/waiting has actually happened, print the up-to-date outcome (`progress`/`interpretedResult`)
    // instead — printing the stale dispatch snapshot after "Operation completed" reads as if nothing
    // happened, or as if the wait never occurred.
    if (envelope.progress) {
        // Default completion summary. An operation can override this via `successMessage` — e.g. install
        // pulls `rollback_version` off the dispatch result and adds a "rollback available" line, since
        // with --wait the human output never dumps `result`. Returning nothing falls back to this default.
        const defaultMessage = `Operation completed: ${envelope.progress.statusMessage || envelope.progress.status}`
        const custom = operation.successMessage?.({
            result: envelope.result,
            progress: envelope.progress,
            defaultMessage,
        })
        const lines = custom !== undefined ? ([] as string[]).concat(custom) : [defaultMessage]
        for (const line of lines) {
            logger.info(line)
        }
        // Only postProcess gets to decide what else a human sees — if it didn't compose a
        // displayMessage, the headline above is all there is
        if (envelope.interpretedResult?.displayMessage) {
            logger.info(envelope.interpretedResult.displayMessage)
        }
        return
    }

    logger.info('Operation completed successfully')
    logger.info(JSON.stringify(envelope.result, null, 2))
}
